kit.scene('ten-heads', {
  init(kit) {
    let heads = '';
    for (let i = 0; i < 9; i++) {
      const a = (-170 + i * 20 + (i >= 4 ? 20 : 0)) * Math.PI / 180, px = 449 + Math.cos(a) * 260, py = 520 + Math.sin(a) * 200 + 60;
      if (i === 4) continue;
      heads += '<g transform="translate(' + px.toFixed(0) + ' ' + py.toFixed(0) + ') scale(' + (i % 2 ? -0.62 : 0.62) + ' 0.62) translate(10 790)">' + W.ravanaHead('ten-heads-h' + i) + '</g>';
    }
    for (const [px, py, f] of [[200, 330, 1], [700, 330, -1]]) heads += '<g transform="translate(' + px + ' ' + py + ') scale(' + (0.6 * f) + ' 0.6) translate(10 790)">' + W.ravanaHead('ten-heads-x' + px) + '</g>';
    const panel = '<rect width="918" height="1027" style="fill:var(--stone)"/><rect x="28" y="28" width="862" height="971" rx="14" style="fill:none;stroke:var(--stoneLit);stroke-width:14;opacity:.6"/>' + W.lace(60, 60, 858, 60, 26, 6) + W.lace(60, 967, 858, 967, 26, 6) +
      '<path d="M140 1027 Q160 860 300 820 L620 820 Q760 860 780 1027 Z" style="fill:color-mix(in srgb, var(--stone) 70%, var(--ink))"/>';
    this.s = W.shot(kit, {
      id: 'ten-heads', back: panel + heads,
      cast: [{ who: 'ravana', x: 470, y: 1300, s: 0.98 }],
      cam: [1.0, 1.05, 459, 513, 459, 500],
      arm: () => 20,
      lines: [],
    });
  },
  render(t) { this.s.render(t); },
});
